    Eq(FromUnix(0), new DateTimeOffset(1970, 1, 1, 0, 0, 0, TimeSpan.Zero)));

Test("2026-01-01T00:00Z -> 1767225600", () =>
    Eq(ToUnixSeconds(new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero)), 1767225600L));

