    Eq(FromUnix(1907742600), new DateTimeOffset(2030, 6, 15, 8, 30, 0, TimeSpan.Zero)));

Test("ToUnixSeconds(FromUnix(123456789)) -> 123456789 (round-trip)", () =>
    Eq(ToUnixSeconds(FromUnix(123456789)), 123456789L));

// ──────────────────────────── tests ──────────────────────────────────────

Test("issued 2026-01-01T00:00Z + 3600 s -> expires 01:00Z", () =>
    Eq(ExpiresAt(new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero), 3600),
       new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero)));

Test("one second before expiry is still valid", () =>
    Eq(IsExpired(new DateTimeOffset(2026, 1, 1, 0, 59, 59, TimeSpan.Zero), new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero)), false));

Test("the instant of expiry is expired (boundary)", () =>
    Eq(IsExpired(new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero), new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero)), true));

Test("one second after expiry is expired", () =>
    Eq(IsExpired(new DateTimeOffset(2026, 1, 1, 1, 0, 1, TimeSpan.Zero), new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero)), true));

Test("a zero TTL is expired the moment it is issued (boundary)", () =>
{
    var issued = new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
    Eq(IsExpired(issued, ExpiresAt(issued, 0)), true);
});

