Test("paying exactly at due + grace is on time (boundary: the edge is inside)", () =>
{
    var due = new DateTimeOffset(2026, 1, 10, 9, 0, 0, TimeSpan.Zero);
    Eq(WithinGrace(due, due.AddMinutes(15), 15), true);
});

