{
    var due = new DateTimeOffset(2026, 1, 10, 9, 0, 0, TimeSpan.Zero);
    Eq(WithinGrace(due, due.AddMinutes(15).AddSeconds(1), 15), false);
});

Test("zero grace: paying exactly at due is on time", () =>
{
    var due = new DateTimeOffset(2026, 1, 10, 9, 0, 0, TimeSpan.Zero);
    Eq(WithinGrace(due, due, 0), true);
