{
    var raw = new DateTime(2026, 4, 1, 12, 0, 0, DateTimeKind.Unspecified);
    Eq(AsUtc(raw).Kind, DateTimeKind.Utc);
});

Test("the clock digits do not move (boundary: relabel, never convert)", () =>
{
    var raw = new DateTime(2026, 4, 1, 12, 0, 0, DateTimeKind.Unspecified);
    Eq(AsUtc(raw).Ticks, raw.Ticks);
});

Test("an already-UTC value passes through unchanged", () =>
{
    var utc = new DateTime(2026, 4, 1, 12, 0, 0, DateTimeKind.Utc);
    var got = AsUtc(utc);
    Eq(got.Ticks, utc.Ticks);
    Eq(got.Kind, DateTimeKind.Utc);
});

Test("IsStorable(Unspecified) -> false", () =>
    Eq(IsStorable(new DateTime(2026, 4, 1, 12, 0, 0, DateTimeKind.Unspecified)), false));

Test("IsStorable(Utc) -> true", () =>
    Eq(IsStorable(new DateTime(2026, 4, 1, 12, 0, 0, DateTimeKind.Utc)), true));

