// ─────────────────────────────────────────────────────────────────────────
//  04 · add months clamp                                       ★★★ stretch
//  concepts: AddMonths clamping · end-of-month policy
// ─────────────────────────────────────────────────────────────────────────
//
//  Jan 31 + 1 month = Feb 28 (AddMonths CLAMPS). Then Feb 28 + 1 month
//  = Mar 28 — the clamp is sticky, and month-end subscribers drift.

using static Bootcamp.Check;

DateOnly NextBilling(DateOnly from)
{
    return from.AddMonths(1);
}

DateOnly AddMonthsKeepEom(DateOnly d, int months)
{
    bool isMonthEnd = d.Day == DateTime.DaysInMonth(d.Year, d.Month);
    var target = d.AddMonths(months);
    if (!isMonthEnd) return target;
    return new DateOnly(target.Year, target.Month, DateTime.DaysInMonth(target.Year, target.Month));
}

// ──────────────────────────── tests ──────────────────────────────────────

